                            "原核销版本不匹配: 当前版本 " + writeoff.version() + ", 请求版本 " + originalVersion);
                }
                repository.insertCorrection(meterKey, fingerprint, writeoffKey, writeoff.allocationKey(),
                        writeoff.windowId(), originalVersion, corrected, meterNanos, trimmedReason, actor,
                        nowNanos());
                return toCorrectionResponse(repository.findCorrectionByKey(meterKey));
