private record BalanceEvent(long nanos, int order, BigDecimal delta) {}

private BigDecimal replayBalance(AllocationRow allocation, Map<String, BigDecimal> effective) {
    List<BalanceEvent> events = new ArrayList<>();
    for (WriteoffRow w : repository.listWriteoffsByAllocation(allocation.allocationKey())) {
        BigDecimal amount = effective.getOrDefault(w.writeoffKey(), w.amount());
        events.add(new BalanceEvent(w.meterNanos(), 0, amount.negate()));
    }
    for (TransferRow t : repository.listTransfersBySource(allocation.allocationKey())) {
        events.add(new BalanceEvent(t.createdNanos(), 1, t.amount().negate()));
    }
    events.sort(Comparator.comparingLong(BalanceEvent::nanos).thenComparingInt(BalanceEvent::order));
    BigDecimal balance = allocation.amount();
    for (BalanceEvent event : events) {
        balance = balance.add(event.delta());
        if (balance.signum() < 0) {
            throw ApiException.unprocessable("NEGATIVE_BALANCE",
                    "更正后历史时点 " + toIso(event.nanos()) + " 之后可用量为负: " + fmt(balance));
        }
    }
    return balance;
}
