private <T> T logRejectionOnFailure(String operation, String meterKey, Long windowId, Supplier<T> body) {
    try {
        return body.get();
    } catch (ApiException e) {
        try {
            tx.execute(status -> {
                repository.insertRejection(windowId, meterKey, operation, e.code(),
                        truncate(e.getMessage()), nowNanos());
                return null;
            });
        } catch (RuntimeException logFailure) {
            // 拒绝日志写入失败不掩盖原业务异常
        }
        throw e;
    }
}

private static String truncate(String message) {
    if (message == null) return "";
    return message.length() <= 500 ? message : message.substring(0, 500);
}

private static String requireReason(String reason) {
    if (reason == null || reason.isBlank()) throw badRequest "reason 不能为空";
    String trimmed = reason.trim();
    if (trimmed.length() > 512) throw badRequest;
    return trimmed;
}

static BigDecimal parseCorrectedAmount(String field, String value) {
    if (value == null || value.isBlank()) throw ...;
    String trimmed = value.trim();
    if (!AMOUNT_PATTERN.matcher(trimmed).matches()) throw badRequest(field + " 必须为不小于 0 的十进制字符串，最多 3 位小数: " + value);
    return new BigDecimal(trimmed);
}
